// @ts-check
import { defineConfig, fontProviders } from 'astro/config';
import starlight from '@astrojs/starlight';
import { readFileSync } from 'node:fs';

// The merged text catalogue, generated by `pnpm catalog` (scripts/catalog/build.mjs).
const catalog = JSON.parse(readFileSync(new URL('./src/data/catalog.json', import.meta.url), 'utf8'));

// https://astro.build/config
export default defineConfig({
	// User/organisation GitHub Pages site, so no `base` is needed.
	site: 'https://meobtis.github.io',
	// Astro Fonts API: fonts are downloaded at build time and self-hosted from /_astro/fonts.
	// The <Font /> tags are rendered in src/components/Head.astro.
	fonts: [
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans',
			cssVariable: '--font-noto-sans',
			weights: [400, 600],
			styles: ['normal', 'italic'],
			// latin-ext covers IAST diacritics (ā ī ū ṛ ṃ ḥ ś ṣ ṇ ṭ ḍ …).
			subsets: ['latin', 'latin-ext'],
			fallbacks: ['sans-serif'],
		},
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans Devanagari',
			cssVariable: '--font-noto-sans-devanagari',
			weights: [400, 600],
			styles: ['normal'],
			subsets: ['devanagari'],
			// No fallbacks: this family is listed *first* in --sl-font and its unicode-range
			// covers only Devanāgarī, so Latin text falls through to Noto Sans (see rosely.css).
			fallbacks: [],
			optimizedFallbacks: false,
		},
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans Mono',
			cssVariable: '--font-noto-sans-mono',
			weights: [400, 600],
			styles: ['normal'],
			subsets: ['latin', 'latin-ext'],
			fallbacks: ['monospace'],
		},
	],
	integrations: [
		starlight({
			title: 'MEOBTIS',
			description: 'Markdown Editions Of Buddhist Texts In Sanskrit',
			logo: { src: './public/favicon.svg' },
			social: [
				{ icon: 'github', label: 'GitHub', href: 'https://github.com/meobtis/meobtis.github.io' },
			],
			editLink: {
				baseUrl: 'https://github.com/meobtis/meobtis.github.io/edit/main/',
			},
			lastUpdated: true,
			components: {
				// Adds Astro's <Font /> tags to every page's <head>.
				Head: './src/components/Head.astro',
			},
			// Rosely palette (same approach as rosely.hellotham.com).
			customCss: ['./src/styles/rosely.css'],
			sidebar: [
				{
					label: 'About',
					items: [
						{ label: 'About MEOBTIS', slug: 'about' },
						{ label: 'Sources', slug: 'about/sources' },
					],
				},
				{
					label: 'Texts',
					items: [
						{ label: 'Overview', link: '/texts/' },
						{ label: 'All texts A–Z', link: '/texts/all/', badge: String(catalog.works.length) },
						// One group per section of the catalogue, one link per category (see scripts/catalog).
						...catalog.groups
							.filter((g) => g.count > 0)
							.map((g) => ({
								label: g.label,
								collapsed: true,
								items: g.categories
									.filter((c) => c.count > 0)
									.map((c) => ({
										label: c.label,
										link: `/texts/${g.id}/${c.id}/`,
										badge: String(c.count),
									})),
							})),
					],
				},
			],
		}),
	],
});
